import datetime
import unittest
from decimal import Decimal

from helpers import CATALOG
import stockroom
from stockroom import ParseError, parse_catalog, parse_movements, parse_orders, stock_levels


def bad(testcase, fn, text, line, *extra):
    with testcase.assertRaises(ParseError) as cm:
        fn(text, *extra)
    testcase.assertEqual(cm.exception.line, line)
    testcase.assertIn("line %d" % line, str(cm.exception))
    testcase.assertIsInstance(cm.exception, ValueError)
    return cm.exception


class CatalogTests(unittest.TestCase):
    def test_example(self):
        c = parse_catalog(CATALOG)
        self.assertEqual(list(c), ["AB-100", "CD-205", "EF-310"])
        p = c["CD-205"]
        self.assertEqual((p.sku, p.name, p.price, p.reorder, p.tax),
                         ("CD-205", "Seed packet, mix", Decimal("1.99"), 40, "reduced"))
        self.assertIsInstance(p.price, Decimal)
        self.assertIsInstance(p.reorder, int)
        self.assertEqual(c["EF-310"].tax, "standard")
        self.assertEqual(c["AB-100"].price, Decimal("12.50"))

    def test_prices(self):
        c = parse_catalog("AB-100|n|12|0\nAB-101|n|12.5|0\nAB-102|n|0.01|0\nAB-103|n|007.10|0\n")
        self.assertEqual([str(p.price) for p in c.values()], ["12.00", "12.50", "0.01", "7.10"])

    def test_bad_prices(self):
        for price in ["12.505", "1,000.00", "-3", "abc", "0", "0.00", "", "1e3", "١٢", "1_000",
                      "NaN", "Infinity", ".5", "5.", "+5", "1 2"]:
            bad(self, parse_catalog, "# c\nAB-100|n|%s|0\n" % price, 2)

    def test_bad_sku(self):
        for sku in ["A-100", "ABCDE-100", "AB-10", "AB-1000", "AB100", "AB_100", "A1-100",
                    "AB-١٠٠", "", "ÀB-100"]:
            bad(self, parse_catalog, "\n\nXX-001|n|1|0\n%s|n|1|0\n" % sku, 4)

    def test_sku_cases(self):
        c = parse_catalog("ab-100|n|1|0\naBcD-999|n|1|0\n")
        self.assertEqual(list(c), ["AB-100", "ABCD-999"])

    def test_duplicate_any_case(self):
        e = bad(self, parse_catalog, "AB-100|n|1|0\n\nab-100|m|1|0\n", 3)

