2024-03-05 CD-205 40
"""
ORDERS = """\
SO-1001 2024-03-03 acme AB-100*12,CD-205*3
SO-1002 2024-03-09 Bea ab-100*2
"""


class Result(object):
    def __init__(self, code, out, err):
        self.code, self.out, self.err = code, out, err


class ShopCase(unittest.TestCase):
    """Runs the CLI as a subprocess against a temporary folder."""

    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self._tmp.cleanup)
        self.dir = self._tmp.name

    def write(self, name, content):
        data = content if isinstance(content, bytes) else content.encode("utf-8")
        with open(os.path.join(self.dir, name), "wb") as f:
            f.write(data)

    def read(self, name):
        with open(os.path.join(self.dir, name), "rb") as f:
            return f.read()

    def exists(self, name):
        return os.path.exists(os.path.join(self.dir, name))

    def shop(self, catalog=CATALOG, movements=MOVEMENTS, orders=ORDERS):
        if catalog is not None:
            self.write("catalog.txt", catalog)
        if movements is not None:
            self.write("movements.txt", movements)
        if orders is not None:
            self.write("orders.txt", orders)

    def run_cli(self, *args, **kw):
        env = dict(os.environ, PYTHONPATH=SRC, PYTHONIOENCODING="utf-8")
        cmd = [sys.executable, "-m", "stockroom"] + list(args)
        if kw.get("dir", True):
            cmd += ["--dir", self.dir]
        p = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env,
                           cwd=kw.get("cwd"))
        return Result(p.returncode, p.stdout.decode("utf-8"), p.stderr.decode("utf-8"))

    def ok(self, *args):
        r = self.run_cli(*args)
        self.assertEqual(r.code, 0, r.err)
        self.assertEqual(r.err, "")
        return r.out

    def fails(self, code, *args, **kw):
        r = self.run_cli(*args, **kw)
        self.assertEqual(r.code, code, r.err)
        self.assertEqual(r.out, "")
        self.assertTrue(r.err.startswith("stockroom:"), r.err)
        return r.err
